import { JSX, useState } from "react";
import { IDispatch } from "../ducks/types";
import { ISettings } from "../types";
import { Thunk_pushScreen, Thunk_importFromLink } from "../ducks/thunks";
import { EditProgram_create, EditProgram_createClassicSplit, EditProgram_createWeekdayProgram } from "../models/editProgram";
import { ModalCreateProgram } from "./modalCreateProgram";
import { ModalImportFromLink } from "./modalImportFromLink";
import { IconDoc } from "./icons/iconDoc";
import { IconEditSquare } from "./icons/iconEditSquare";
import { IconLink } from "./icons/iconLink";
import { emptyProgramId, Program_selectProgram } from "../models/program";
import { IconEquipmentKettlebell } from "./icons/iconEquipmentKettlebell";
import { IconFire } from "./icons/iconFire";

interface IScreenProgramSelectProps {
  dispatch: IDispatch;
  settings: ISettings;
}

export function ScreenProgramSelect(props: IScreenProgramSelectProps): JSX.Element {
  const [shouldCreateProgram, setShouldCreateProgram] = useState(false);
  const [showImportFromLink, setShowImportFromLink] = useState(false);

  const options = [
    {
      key: "classic-split",
      icon: <IconFire size={24} />,
      title: "Use your classic split",
      description: "Load the 6-day body-part plan with cardio notes and the 12-week roadmap",
      onClick: () => EditProgram_createClassicSplit(props.dispatch),
    },
    {
      key: "weekday",
      icon: <IconEditSquare />,
      title: "Create weekly plan",
      description: "Start with Monday through Sunday and edit each day for your routine",
      onClick: () => EditProgram_createWeekdayProgram(props.dispatch, "My Weekly Plan"),
    },
    {
      key: "advanced",
      icon: <IconDoc width={24} height={24} />,
      title: "Advanced editor",
      description: "Create a blank planner and use Liftosaur's full program editor",
      onClick: () => setShouldCreateProgram(true),
    },
    {
      key: "builtin",
      icon: <IconDoc width={24} height={24} />,
      title: "Browse templates",
      description: "Open the built-in program browser as a secondary path",
      onClick: () => props.dispatch(Thunk_pushScreen("programs")),
    },
    {
      key: "import",
      icon: <IconLink size={24} />,
      title: "Import plan",
      description: "Paste a program link or restore a shared routine into your local app",
      onClick: () => setShowImportFromLink(true),
    },
    {
      key: "adhoc",
      icon: <IconEquipmentKettlebell size={24} />,
      title: "Track without a plan",
      description: "Use ad hoc workouts now and build the weekly plan later",
      onClick: () => Program_selectProgram(props.dispatch, emptyProgramId),
    },
  ];

  return (
    <section className="flex flex-col h-screen text-text-primary bg-background-default">
      <div className="flex-1 px-4 pt-8 pb-4 overflow-y-auto">
        <div className="p-4 text-center">
          <img
            src="/images/dinoprogramselect.png"
            className="inline-block object-cover h-52"
            alt="Workout planner"
          />
        </div>
        <div className="px-2 -mt-1">
          <h2 className="mb-2 text-xl font-bold text-center text-text-primary">Set up your training week</h2>
          <p className="mb-6 text-sm text-center text-text-secondary">
            Pick the fastest way to start your offline workout tracker.
          </p>

          <div className="space-y-3">
            {options.map((opt) => (
              <button
                key={opt.key}
                className="flex items-center w-full gap-3 px-4 py-4 text-left border rounded-xl bg-background-subtlecardpurple border-border-cardpurple nm-program-select"
                data-cy={`program-select-${opt.key}`}
                onClick={opt.onClick}
              >
                <div className="text-text-secondary">{opt.icon}</div>
                <div className="flex-1">
                  <div className="text-sm font-semibold">{opt.title}</div>
                  <div className="text-xs text-text-secondary">{opt.description}</div>
                </div>
                <div className="text-text-secondary">
                  <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                    <path
                      d="M6 4l4 4-4 4"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </div>
              </button>
            ))}
          </div>
        </div>
      </div>

      <ModalCreateProgram
        isHidden={!shouldCreateProgram}
        onClose={() => setShouldCreateProgram(false)}
        onSelect={(name) => {
          EditProgram_create(props.dispatch, name);
        }}
      />
      <ModalImportFromLink
        isHidden={!showImportFromLink}
        onSubmit={async (link) => {
          if (link) {
            props.dispatch(Thunk_importFromLink(link));
          }
          setShowImportFromLink(false);
        }}
      />
    </section>
  );
}
